import React, { useState, useEffect } from 'react';
import { Menu, X, Home, Sun, Moon } from 'lucide-react';
import collegeLogo from '../../assets/cec122.png';

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [darkMode, setDarkMode] = useState(false);

    useEffect(() => {
        const savedTheme = localStorage.getItem('theme');
        if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
            setDarkMode(true);
            document.documentElement.classList.add('dark');
        } else {
            setDarkMode(false);
            document.documentElement.classList.remove('dark');
        }
    }, []);

    const toggleTheme = () => {
        if (darkMode) {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
            setDarkMode(false);
        } else {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
            setDarkMode(true);
        }
    };

    return (
        <nav className="sticky top-0 z-[999] shadow-[0_2px_20px_rgba(10,22,40,0.08)] dark:shadow-none dark:border-b dark:border-slate-800">
            {/* Top Tier: Logo and College Info */}
            <div className="bg-cream dark:bg-slate-900 py-3 transition-colors duration-300">
                <div className="flex w-full items-center justify-start gap-[20px] px-4 lg:px-8">
                    {/* College Logo */}
                    <img src={collegeLogo} alt="CEC Logo" className="h-[120px] w-[120px] shrink-0 object-contain rounded-sm shadow-sm dark:bg-white p-1" />
                    <div className="flex flex-col justify-center text-left flex-1 border-r border-transparent">
                        <h1 className="font-display text-[2.2rem] font-extrabold leading-tight text-coral dark:text-coral-alt uppercase mb-1 tracking-wide">
                            College Of Engineering Chengannur
                        </h1>
                        <p className="text-[1.1rem] font-bold tracking-[0.02em] text-slate-800 dark:text-gray-200">
                            ESTD : 1993 managed by IHRD, A Govt of Kerala Undertaking
                        </p>
                        <p className="text-[1.05rem] font-semibold tracking-[0.02em] text-slate-700 dark:text-gray-400 mt-[2px]">
                            Affiliated to A P J Abdul Kalam Technological University, Kerala
                        </p>
                    </div>
                    
                    {/* Theme Toggle Button */}
                    <div className="ml-auto pl-4 border-l border-slate-300 dark:border-slate-700">
                        <button 
                            onClick={toggleTheme} 
                            className="flex items-center justify-center p-3 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors focus:outline-none focus:ring-2 focus:ring-coral dark:focus:ring-gold"
                            aria-label="Toggle Dark Mode"
                            title="Toggle Dark Mode"
                        >
                            {darkMode ? (
                                <Sun size={26} className="text-gold. animate-[pulse_3s_ease-in-out_infinite]" />
                            ) : (
                                <Moon size={26} className="text-slate-700" />
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* Bottom Tier: Navigation Links */}
            <div className="bg-coral dark:bg-coral2 transition-colors duration-300">
                <div className="relative flex w-full items-center px-4 lg:px-8">
                    <ul
                        className={`${isOpen ? 'flex' : 'hidden'} absolute left-0 top-full w-full flex-col bg-coral dark:bg-slate-800 py-2 text-[1rem] font-semibold tracking-[0.03em] text-white shadow-[0_8px_20px_rgba(10,22,40,0.1)] md:static md:flex md:w-auto md:flex-row md:py-0 md:bg-transparent md:dark:bg-transparent md:shadow-none w-full justify-between flex-wrap`}
                    >
                        <li>
                            <a href="#home" onClick={() => setIsOpen(false)} className="flex items-center gap-1 block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">
                                <Home size={20} /> HOME
                            </a>
                        </li>
                        <li><a href="#about" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">ABOUT</a></li>
                        <li><a href="#administration" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">ADMINISTRATION</a></li>
                        <li><a href="#academics" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">ACADEMICS</a></li>
                        <li><a href="#research" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">RESEARCH</a></li>
                        <li><a href="#placement" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">PLACEMENT</a></li>
                        <li><a href="#examination" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">EXAMINATION</a></li>
                        <li><a href="#facilities" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">FACILITIES</a></li>
                        <li><a href="#campus" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">CAMPUS</a></li>
                        <li><a href="#quick" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">QUICK LINKS</a></li>
                        <li><a href="#gallery" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">GALLERY</a></li>
                        <li><a href="#achievements" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">ACHIEVEMENTS</a></li>
                        <li><a href="#organisations" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">ORGANISATIONS</a></li>
                        <li><a href="#contact" onClick={() => setIsOpen(false)} className="block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 dark:hover:bg-slate-700 hover:text-gold md:py-[14px]">CONTACT</a></li>
                    </ul>
                    <button
                        onClick={() => setIsOpen(!isOpen)}
                        className="ml-auto block p-[10px] text-white md:hidden my-2"
                        aria-label="Menu"
                    >
                        {isOpen ? <X size={24} /> : <Menu size={24} />}
                    </button>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
